// Load state: last processed file IDs per folder
const staticData = $getWorkflowStaticData('global');
const lastRun = staticData.lastRun || {};

// Health Sync Google Drive folder IDs
// REPLACE THESE with actual Google Drive folder IDs
const folders = {
  'Health Sync Steps':           '113y4ZIRKmbBm96Uo_lPVpTjkVu7zXulY',
  'Health Sync Heart rate':      '10IkFt7tAl_m0CZpp7d3ienTQrJrdH3uq',
  'Health Sync Sleep':           '1VVACpLXTpR1ilnpnnzQf7TYcAqyaiGx0',
  'Health Sync Energy burned':   '1iWCZXxnMKqDep0gnmZgIVozMJGZZ9bun',
  'Health Sync Activities':      '1CMrcyqBCvGR8a0niDh2IZMo4MrmNWFXl',
  'Health Sync Weight':          '10TadE9PkwqJ3av9jc7ghzv8Bkvx5axGF',
  'Health Sync Oxygen saturation': '19vi1YNxIc13e8lEVO3vIfok6bfOJCs2e',
};

return [{ json: { folders, lastRun, runTime: new Date().toISOString() } }];

// Parse CSV and map to PostgreSQL schema
const meta = $('Check File Ledger').item.json;
const folderName = meta.folder_name;
const fileName = meta.file_name;
const csvBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const csvText = csvBuffer.toString('utf-8');

// Simple CSV parser (handles commas in fields, quoted values)
function parseCSV(text) {
  const records = [];
  let record = [], field = '', quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (ch === '"') quoted = false;
      else field += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { record.push(field); field = ''; }
    else if (ch === '\n') {
      record.push(field.replace(/\r$/, ''));
      if (record.some(value => value !== '')) records.push(record);
      record = []; field = '';
    } else field += ch;
  }
  if (field || record.length) {
    record.push(field.replace(/\r$/, ''));
    if (record.some(value => value !== '')) records.push(record);
  }
  if (records.length < 2) return [];
  const headers = records[0].map(value => value.replace(/^\uFEFF/, '').trim());
  return records.slice(1).map(values => Object.fromEntries(
    headers.map((header, index) => [header, values[index] ?? ''])
  ));
}

function parseDate(dateStr) {
  // Format: YYYY.MM.DD HH:MM:SS
  const match = dateStr.match(/(\d{4})\.(\d{2})\.(\d{2})\s+(\d{2}):(\d{2}):(\d{2})/);
  if (!match) return null;
  const [_, y, m, d, h, min, s] = match;
  const guess = Date.UTC(+y, +m - 1, +d, +h, +min, +s);
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23'
  }).formatToParts(new Date(guess)).filter(p => p.type !== 'literal').map(p => [p.type, p.value]));
  const representedAsUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute, +parts.second);
  return new Date(guess - (representedAsUtc - guess));
}

function sha256(parts) {
  // Simple hash for dedup — n8n doesn't have crypto built-in, use filename+date
  return parts.join('\0');
}

const rows = parseCSV(csvText);
const observations = [];

// Source name from folder path
function sourceName(file) {
  if (file.includes('Samsung Health')) return 'Health Sync / Samsung Health';
  if (file.includes('Google Fit')) return 'Health Sync / Google Fit';
  if (file.includes('Health Connect')) return 'Health Sync / Health Connect';
  return 'Health Sync';
}

const src = sourceName(fileName);

for (const row of rows) {
  const dateStr = row['Date'] || row['date'] || '';
  const dt = parseDate(dateStr);
  if (!dt) continue;
  const isoStart = dt.toISOString();

  if (folderName === 'Health Sync Steps') {
    const val = parseFloat(row['Steps']);
    if (!isNaN(val) && val > 0) {
      observations.push({
        metric_type: 'steps',
        original_type: 'health_sync_steps',
        start_time: isoStart,
        end_time: isoStart,
        value_numeric: val,
        value_text: null,
        unit: 'count',
        source_name: src,
        external_id: `hs_steps_${dateStr}_${val}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }
  }

  else if (folderName === 'Health Sync Heart rate') {
    const val = parseFloat(row['Heart rate']);
    if (!isNaN(val) && val > 0) {
      observations.push({
        metric_type: 'heart_rate',
        original_type: 'health_sync_heart_rate',
        start_time: isoStart,
        end_time: isoStart,
        value_numeric: val,
        value_text: null,
        unit: 'count/min',
        source_name: src,
        external_id: `hs_hr_${dateStr}_${val}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }
  }

  else if (folderName === 'Health Sync Oxygen saturation') {
    const val = parseFloat(row['Oxygen saturation']);
    if (!isNaN(val) && val > 0) {
      observations.push({
        metric_type: 'oxygen_saturation',
        original_type: 'health_sync_oxygen_saturation',
        start_time: isoStart,
        end_time: isoStart,
        value_numeric: val,
        value_text: null,
        unit: '%',
        source_name: src,
        external_id: `hs_o2_${dateStr}_${val}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }
  }

  else if (folderName === 'Health Sync Energy burned') {
    const mapping = [
      ['Active calories', 'active_energy', 'health_sync_active_calories'],
      ['Resting calories', 'basal_energy', 'health_sync_resting_calories'],
      ['Total calories', 'calories', 'health_sync_total_calories'],
    ];
    for (const [col, metric, orig] of mapping) {
      const val = parseFloat(row[col]);
      if (!isNaN(val) && val !== 0) {
        observations.push({
          metric_type: metric,
          original_type: orig,
          start_time: isoStart,
          end_time: isoStart,
          value_numeric: val,
          value_text: null,
          unit: 'kcal',
          source_name: src,
          external_id: `hs_${orig}_${dateStr}_${val}`,
          raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
        });
      }
    }
  }

  else if (folderName === 'Health Sync Sleep') {
    const duration = parseFloat(row['Duration in seconds']);
    const stage = (row['Sleep stage'] || '').trim().toLowerCase();
    if (!isNaN(duration) && duration > 0 && stage) {
      const endMs = dt.getTime() + duration * 1000;
      const isoEnd = new Date(endMs).toISOString();
      observations.push({
        metric_type: 'sleep_segment',
        original_type: 'health_sync_sleep_stage',
        start_time: isoStart,
        end_time: isoEnd,
        value_numeric: null,
        value_text: stage,
        unit: null,
        source_name: src,
        external_id: `hs_sleep_${dateStr}_${duration}_${stage}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }
  }

  else if (folderName === 'Health Sync Activities') {
    const activity = row['Activity type'] || 'activity';
    const elapsed = parseFloat(row['Elapsed time']) || 0;
    const active = parseFloat(row['Active time']);
    const endMs = dt.getTime() + elapsed * 1000;
    const isoEnd = new Date(endMs).toISOString();

    observations.push({
      metric_type: 'activity_segment',
      original_type: 'health_sync_activity',
      start_time: isoStart,
      end_time: isoEnd,
      value_numeric: isNaN(active) ? null : active,
      value_text: activity,
      unit: 's',
      source_name: src,
      external_id: `hs_act_${dateStr}_${activity}_${elapsed}`,
      raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
    });

    // Distance
    const dist = parseFloat(row['Distance (miles)']);
    if (!isNaN(dist) && dist > 0) {
      observations.push({
        metric_type: 'distance',
        original_type: 'health_sync_activity_distance',
        start_time: isoStart,
        end_time: isoEnd,
        value_numeric: dist * 1609.344,
        value_text: null,
        unit: 'm',
        source_name: src,
        external_id: `hs_dist_${dateStr}_${dist}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }

    // Calories
    const cals = parseFloat(row['Calories (kcal)']);
    if (!isNaN(cals) && cals > 0) {
      observations.push({
        metric_type: 'active_energy',
        original_type: 'health_sync_activity_calories',
        start_time: isoStart,
        end_time: isoEnd,
        value_numeric: cals,
        value_text: null,
        unit: 'kcal',
        source_name: src,
        external_id: `hs_cal_${dateStr}_${cals}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }

    // Avg HR
    const hr = parseFloat(row['Average heart rate']);
    if (!isNaN(hr) && hr > 0) {
      observations.push({
        metric_type: 'heart_rate',
        original_type: 'health_sync_activity_avg_hr',
        start_time: isoStart,
        end_time: isoEnd,
        value_numeric: hr,
        value_text: null,
        unit: 'count/min',
        source_name: src,
        external_id: `hs_act_hr_${dateStr}_${hr}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }
  }

  else if (folderName === 'Health Sync Weight') {
    const val = parseFloat(row['Weight']);
    if (!isNaN(val) && val > 0) {
      observations.push({
        metric_type: 'weight',
        original_type: 'health_sync_weight',
        start_time: isoStart,
        end_time: isoStart,
        value_numeric: val,
        value_text: null,
        unit: row['Unit'] || 'kg',
        source_name: src,
        external_id: `hs_weight_${dateStr}_${val}`,
        raw_payload_json: JSON.stringify({fileId: meta.file_id, fileName, folderName, row})
      });
    }
  }
}

return {json: {...meta, observations}};

return $input.all().filter(i => i.json.id).map(i => ({json:{
  file_id:i.json.id, file_name:i.json.name, version_key:String(i.json.modifiedTime||'1'),
  modified_time:i.json.modifiedTime||null, md5_checksum:i.json.md5Checksum||null,
  folder_id:i.json.folder_id, folder_name:i.json.folder_name, cutoff_day:i.json.cutoff_day,
  cutoff_reason:i.json.cutoff_reason, latest_observation_et:i.json.latest_observation_et,
  candidate_day:i.json.candidate_day
}}));

const cutoffs = new Map(
  $('Determine Recovery Cutoff').all().map(item => [String(item.json.folder_id), item.json])
);
const token = /\b(\d{4}\.\d{2}\.\d{2})\b/g;
const candidates = new Map();

for (const item of $input.all()) {
  const name = String(item.json.name || '');
  const dates = [...name.matchAll(token)].map(match => match[1]);
  const parentId = String((item.json.parents || [])[0] || '');
  const cutoff = cutoffs.get(parentId);
  if (!item.json.id || !cutoff || dates.length !== 1 || !/\bHealth Connect\.csv$/i.test(name)) continue;

  const cutoffDay = String(cutoff.cutoff_day).slice(0, 10).replace(/-/g, '.');
  if (dates[0] < cutoffDay) continue;

  // One authoritative daily file per folder/date. A newer Drive version wins;
  // ID is a deterministic tie-breaker. This excludes duplicate feeds before landing.
  const candidate = {json: {
    ...item.json,
    folder_id: cutoff.folder_id,
    folder_name: cutoff.folder_name,
    cutoff_day: cutoffDay,
    cutoff_reason: cutoff.cutoff_reason,
    latest_observation_et: cutoff.latest_observation_et,
    candidate_day: dates[0],
  }};
  const key = `${candidate.json.folder_id}\0${candidate.json.candidate_day}`;
  const previous = candidates.get(key);
  const candidateVersion = `${candidate.json.modifiedTime || ''}\0${candidate.json.id}`;
  const previousVersion = previous ? `${previous.json.modifiedTime || ''}\0${previous.json.id}` : '';
  if (!previous || candidateVersion > previousVersion) candidates.set(key, candidate);
}

return [...candidates.values()].sort((a, b) =>
  a.json.folder_name.localeCompare(b.json.folder_name) ||
  a.json.candidate_day.localeCompare(b.json.candidate_day)
);
